using Gtk 4.0;
using Adw 1;

template $GduBenchmarkDialog: Adw.Dialog {
  title: _("Benchmark");

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: bind close_button.visible inverted;

      [start]
      Button close_button {
        label: _("_Cancel");
        use-underline: true;
        action-name: "window.close";
      }

      [start]
      Button cancel_button {
        label: _("_Cancel");
        use-underline: true;
        visible: bind close_button.visible inverted;
        clicked => $on_cancel_clicked_cb() swapped;
      }

      [end]
      Button {
        label: _("_Start…");
        use-underline: true;
        clicked => $on_start_clicked_cb() swapped;
        visible: bind close_button.visible bidirectional;

        styles [
          "suggested-action",
        ]
      }

      title-widget: Adw.WindowTitle window_title {
        title: _("Benchmark");
      };
    }

    content: Stack pages_stack {
      transition-type: crossfade;

      StackPage {
        name: "options";

        child: Adw.PreferencesPage {
          description: _(
            "Benchmarking measures the transfer rate for different areas of the disk. It also measures seek times from one area to another."
          );

          Adw.PreferencesGroup {
            Adw.SpinRow sample_row {
              title: _("Transfer S_amples");
              use-underline: true;

              adjustment: Adjustment {
                lower: 2;
                upper: 1000;
                value: 100;
                step-increment: 1;
                page-increment: 10;
              };
            }

            Adw.SpinRow sample_size_row {
              title: _("Transfer Sample S_ize");
              use-underline: true;
              output => $set_sample_size_unit_cb();

              adjustment: Adjustment {
                lower: 2;
                upper: 1000;
                value: 100;
                step-increment: 1;
                page-increment: 10;
              };
            }

            Adw.SpinRow access_samples_row {
              title: _("_Access Time Samples");
              use-underline: true;

              adjustment: Adjustment {
                lower: 2;
                upper: 10000;
                value: 100;
                step-increment: 1;
                page-increment: 10;
              };
            }
          }

          Adw.PreferencesGroup {
            Adw.SwitchRow write_bench_switch {
              title: _("_Write Benchmark");
              use-underline: true;
              subtitle: _("Data should be backed up before using this feature");
            }
          }
        };
      }

      StackPage {
        name: "results";

        child: Adw.PreferencesPage {
          Adw.PreferencesGroup {
            $GduBenchmarkGraph benchmark_graph {}
          }

          Adw.PreferencesGroup {
            Adw.ActionRow sample_size_action_row {
              title: _("Sample Size");
              subtitle: "-";

              styles [
                "property",
              ]
            }

            Adw.ActionRow read_rate_row {
              title: _("Average Read Rate");
              subtitle: "-";
              use-markup: true;

              styles [
                "property",
              ]
            }

            Adw.ActionRow write_rate_row {
              title: _("Average Write Rate");
              subtitle: "-";
              use-markup: true;

              styles [
                "property",
              ]
            }

            Adw.ActionRow access_time_row {
              title: _("Average Access Time");
              subtitle: "-";
              use-markup: true;

              styles [
                "property",
              ]
            }
          }
        };
      }
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GduBlockRow: Adw.ExpanderRow {
  [prefix]
  Box button {
    Label partition_depth_label {
      visible: false;
    }

    Image partition_image {
      halign: center;
      valign: center;
      margin-start: 6;
      margin-end: 6;
      width-request: 20;
      height-request: 20;

      styles [
        "partition-row",
      ]
    }
  }

  [suffix]
  Box {
    spacing: 12;

    Spinner job_indicator_spinner {}

    Adw.Clamp {
      halign: end;
      maximum-size: 160;
      tightening-threshold: 160;

      child: LevelBar space_level_bar {
        visible: false;
        valign: center;
        hexpand: true;
        width-request: 80;
        height-request: 18;
      };
    }

    Button create_partition_button {
      tooltip-text: _("Create Partition");
      valign: center;
      icon-name: "list-add-symbolic";
      action-name: "row.create_partition";
      visible: false;

      styles [
        "flat",
      ]
    }

    MenuButton block_menu_button {
      tooltip-text: _("Partition Options");
      valign: center;
      menu-model: block_menu;
      icon-name: "view-more-symbolic";
      visible: bind create_partition_button.visible inverted;

      styles [
        "flat",
      ]
    }
  }

  Adw.ActionRow size_row {
    title: _("Size");
    subtitle-selectable: true;

    styles [
      "property",
    ]
  }

  Adw.ActionRow device_id_row {
    title: _("Device ID");
    subtitle-selectable: true;

    styles [
      "property",
    ]
  }

  Adw.ActionRow uuid_row {
    title: _("UUID");
    subtitle-selectable: true;

    styles [
      "property",
    ]
  }

  Adw.ActionRow partition_type_row {
    title: _("Partition Type");
    subtitle-selectable: true;

    styles [
      "property",
    ]
  }
}

menu block_menu {
  section volume_actions_submenu {
    item (_("Resize…"), "row.resize")

    submenu {
      label: _("Edit");

      /* Translators: TRANSLATORS: this should be phrased as a noun. */
      item (_("Partition…"), "row.edit_partition")
      item (_("Filesystem…"), "row.edit_filesystem")
      item (_("Change Passphrase…"), "row.change_passphrase")
      item (_("Mount Options…"), "row.configure_fstab")
      item (_("Encryption Options…"), "row.configure_crypttab")
      item (_("Take Ownership…"), "row.take_ownership")
    }

    item (_("Format Partition…"), "row.format_partition")
    item (_("Delete…"), "row.delete")
  }

  section {
    item (_("Check Filesystem…"), "row.check_fs")
    item (_("Repair Filesystem…"), "row.repair_fs")
    item (_("Benchmark Partition…"), "row.benchmark_partition")
  }

  section {
    item (_("Create Partition Image…"), "row.create_partition_image")
    item (_("Restore Partition Image…"), "row.restore_partition_image")
  }
}

using Gtk 4.0;
using Adw 1;

template $GduChangePassphraseDialog: Adw.Dialog {
  title: _("Change Passphrase");
  content-width: 590;
  content-height: 320;

  Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-start-title-buttons: false;
      show-end-title-buttons: false;

      [start]
      Button {
        use-underline: true;
        label: _("_Cancel");
        action-name: "window.close";
      }

      title-widget: Adw.WindowTitle window_title {
        title: _("Change Passphrase");
      };

      [end]
      Button change_pass_button {
        use-underline: true;
        sensitive: false;
        label: _("Ch_ange");
        clicked => $on_change_passphrase_clicked() swapped;

        styles [
          "suggested-action",
        ]
      }
    }

    content: Box {
      orientation: vertical;

      Adw.Banner banner {
        title: _(
          "Changing the passphrase for this device will also update the passphrase referenced by the <i>/etc/crypttab</i> file"
        );
        use-markup: true;
      }

      Adw.PreferencesPage {
        Adw.PreferencesGroup {
          Adw.PasswordEntryRow curr_pass_row {
            title: _("C_urrent Password");
            use-underline: true;
            notify::text => $on_dialog_entry_changed() swapped;
          }

          Adw.PasswordEntryRow new_pass_row {
            title: _("_New Password");
            use-underline: true;
            notify::text => $on_dialog_entry_changed() swapped;
          }

          Adw.PasswordEntryRow confirm_pass_row {
            title: _("C_onfirm Password");
            use-underline: true;
            notify::text => $on_dialog_entry_changed() swapped;
          }

          LevelBar strength_indicator {
            mode: continuous;
            max-value: 5;
            margin-top: 12;

            offsets [
              offset ("strength-weak", 1),
              offset ("strength-low", 2),
              offset ("strength-medium", 3),
              offset ("strength-good", 4),
              offset ("strength-high", 5),
            ]
          }

          Label strength_hint_label {
            margin-top: 6;
            wrap: true;
            natural-wrap-mode: none;

            styles [
              "dim-label",
              "explanation-label",
            ]
          }
        }
      }
    };
  }
}

using Gtk 4.0;
using Adw 1;

template $GduCreateConfirmPage: Adw.Bin {
