    Adw.PreferencesGroup {
      Adw.ActionRow device_row {
        title: _("Device");

        styles [
          "property",
        ]
      }

      Adw.ActionRow volume_row {
        title: _("Volume");

        styles [
          "property",
        ]
      }

      Adw.ActionRow usage_row {
        title: _("Used");
        visible: false;

        styles [
          "property",
        ]
      }

      Adw.ActionRow location_row {
        title: _("Location");

        styles [
          "property",
        ]
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GduCreateDiskImageDialog: Adw.Dialog {
  content-width: 440;
  title: "Create Disk Image";

  Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-start-title-buttons: false;
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("_Cancel");
        use-underline: true;
        action-name: "window.close";
      }

      [end]
      Button create_image_button {
        label: _("C_reate");
        use-underline: true;
        clicked => $on_create_image_button_clicked_cb(template);

        styles [
          "suggested-action",
        ]
      }
    }

    content: Adw.PreferencesPage {
      Adw.PreferencesGroup {
        Adw.EntryRow name_entry {
          title: _("_Name");
          use-underline: true;
        }

