          title: _("Location");

          [suffix]
          Button {
            tooltip-text: _("Select Location");
            valign: center;
            icon-name: "folder-open-symbolic";
            clicked => $on_choose_folder_button_clicked_cb(template);

            styles [
              "flat",
            ]
          }

          styles [
            "property",
          ]
        }

        Adw.ActionRow source_label {
          title: _("Source");

          styles [
            "property",
          ]
        }
      }
    };
  }
}

using Gtk 4.0;
using Adw 1;

template $GduCreateFilesystemPage: Adw.Bin {
  notify::fs-type => $on_fs_type_changed(template);

  Adw.PreferencesPage {
    Adw.PreferencesGroup {
      Adw.EntryRow name_entry {
        title: _("_Volume Name");
        use-underline: true;
        apply => $on_fs_name_changed(template);
      }
    }

    Adw.PreferencesGroup {
      Adw.ActionRow {
        title: _("_Overwrite Existing Data");
        use-underline: true;
        activatable-widget: erase_switch;

        [suffix]
        MenuButton {
          tooltip-text: _("More Information");
          icon-name: "help-about-symbolic";
          valign: center;

          popover: Popover {
            child: Label {
              halign: center;
              margin-start: 6;
              margin-end: 6;
              margin-top: 6;
              margin-bottom: 6;
              label: _("Ensures that existing data cannot be recovered. This option slows down formatting.");
              wrap: true;
              max-width-chars: 50;
              valign: center;
            };
          };

          styles [
            "flat",
          ]
        }

        [suffix]
        Switch erase_switch {
          valign: center;
        }
      }
    }

    Adw.PreferencesGroup {
      title: _("Type");

      Adw.ActionRow {
        title: "E_xt4";
        subtitle: _("For use only with Linux systems");
        use-underline: true;
        activatable-widget: ext4_checkbutton;

        [prefix]
        CheckButton ext4_checkbutton {
          action-name: "update_fs_type";
          action-target: "'ext4'";
        }
      }

      Adw.ActionRow {
        title: "N_TFS";
        subtitle: _("For use with Windows");
        use-underline: true;
        activatable-widget: ntfs_checkbutton;

        [prefix]
        CheckButton ntfs_checkbutton {
          action-name: "update_fs_type";
          action-target: "'ntfs'";
        }
      }

      Adw.ActionRow {
        title: "_FAT";
        subtitle: _("For use with all systems and devices");
        use-underline: true;
        activatable-widget: fat_checkbutton;

        [prefix]
        CheckButton fat_checkbutton {
          action-name: "update_fs_type";
          action-target: "'vfat'";
        }
      }

      Adw.ActionRow {
        title: "Ot_her";
        use-underline: true;
        activatable-widget: other_checkbutton;

        [prefix]
        CheckButton other_checkbutton {
          action-name: "update_fs_type";
          action-target: "'other'";
        }
      }
    }

    Adw.PreferencesGroup {
      Adw.SwitchRow encrypt_switch {
        title: _("_Password Protect Volume");
        subtitle: _("Encrypts the volume using LUKS");
        use-underline: true;
        notify::active => $on_fs_type_changed(template);
        sensitive: bind ext4_checkbutton.active;
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GduCreateOtherPage: Adw.Bin {
  Adw.PreferencesPage {
    Adw.PreferencesGroup fs_types_group {
      title: _("Type");
    }

    Adw.PreferencesGroup {
      Adw.SwitchRow encrypt_switch {
        title: _("Password Protect Volume");
        subtitle: _("Encrypts the volume using LUKS");
        notify::active => $on_fs_type_changed(template);
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GduCreatePartitionPage: Adw.Bin {
  Box {
    orientation: vertical;

    Adw.Banner top_banner {}

    Adw.PreferencesPage {
      Adw.PreferencesGroup {
        Scale {
          adjustment: size_adjustment;
        }
      }

      Adw.PreferencesGroup {
        Adw.SpinRow size_row {
          title: _("Partition Size");
          output => $set_size_entry_unit_cb();

          adjustment: Adjustment size_adjustment {
            upper: 100;
            step-increment: 1;
            page-increment: 10;
            value-changed => $on_size_changed_cb() swapped;
          };
        }

        Adw.SpinRow free_space_row {
          title: _("Free Space");
          subtitle: _("Space following new partition");
          output => $set_size_entry_unit_cb();

          adjustment: Adjustment free_following_adjustment {
            step-increment: 1;
            page-increment: 10;
            upper: bind size_adjustment.upper;
          };
        }
      }

      Adw.PreferencesGroup {
        visible: bind dos_extended_row.visible;

        Adw.SwitchRow dos_extended_row {
          title: _("Extended Partition");
          subtitle: _("Extended Partitions can contain Logical Partitions");
          visible: false;
          notify::active => $on_part_type_changed(template);
        }
      }

      Adw.PreferencesGroup {
        Adw.ComboRow size_unit_combo {
          title: _("Units");
          notify::selected => $on_size_unit_changed_cb(template);

          model: StringList {
            strings [
              _("bytes"),
              _("kB"),
              _("MB"),
              _("GB"),
              _("TB"),
              _("PB"),
              _("KiB"),
              _("MiB"),
              _("GiB"),
              _("TiB"),
              _("PiB"),
            ]
          };
        }
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GduCreatePasswordPage: Adw.Bin {
  Adw.PreferencesPage {
    Adw.PreferencesGroup {
      description: _(
        "Data stored in the Volume will only be accessible with the correct password. Be careful not to forget it"
      );

      Adw.PasswordEntryRow password_entry {
        title: _("Password");
        notify::text => $on_password_changed(template);
      }

      Adw.PasswordEntryRow confirm_password_entry {
        title: _("Confirm Password");
        sensitive: false;
        notify::text => $on_password_changed(template);
      }

      Label confirm_password_label {
        label: _("The passwords do not match.");
        visible: false;
        margin-top: 12;
      }

      LevelBar strength_indicator {
        mode: continuous;
        max-value: 5;
        margin-top: 12;

        offsets [
          offset ("strength-weak", 1),
          offset ("strength-low", 2),
          offset ("strength-medium", 3),
          offset ("strength-good", 4),
          offset ("strength-high", 5),
        ]
      }

      Label strength_hint_label {
        margin-top: 6;
        wrap: true;
        natural-wrap-mode: none;

        styles [
          "dim-label",
          "explanation-label",
        ]
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

Adw.Dialog disk-settings-dialog {
  title: _("Drive Settings");
  content-width: 500;
  content-height: 300;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-start-title-buttons: false;
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("_Cancel");
        use-underline: true;
        halign: start;
        hexpand: true;
        action-name: "window.close";
      }

      title-widget: Adw.WindowTitle window_title {
        title: _("Drive Settings");
      };

      [end]
      Button ok-button {
        label: _("Sa_ve");
        use-underline: true;

        styles [
          "suggested-action",
        ]
      }
    }

    Notebook notebook1 {
      margin-start: 12;
      margin-end: 12;
      margin-top: 12;
      margin-bottom: 12;

      Box standby-box {
        orientation: vertical;
        spacing: 6;
        margin-start: 12;
        margin-end: 12;
        margin-top: 12;
        margin-bottom: 12;

        Box {
          spacing: 12;

          Label {
            label: _("Apply Standby Timeout Settings");
            hexpand: true;
            xalign: 0;
            ellipsize: end;

            styles [
              "heading",
            ]
          }

          Switch standby-switch {
            has-tooltip: true;
            tooltip-text: _("Turn on to configure Standby Timeout at startup and when the disk is connected");
          }
        }

        Box standby-widgets-box {
          orientation: vertical;
          spacing: 6;

          Box {
            spacing: 6;

            Label {
              xalign: 1;
              label: _("Enter Standby After");

              styles [
                "dim-label",
              ]
            }

            Label standby-value-label {}
          }

          Scale standby-scale {
            margin-start: 24;
            margin-end: 24;

            adjustment: Adjustment standby-adjustment {
              upper: 255;
              value: 60;
              step-increment: 1;
              page-increment: 10;
            };

            draw-value: false;
          }
        }
      }

      [tab]
      Label {
        label: _("_Standby");
        use-underline: true;
      }

      Box apm-box {
        orientation: vertical;
        spacing: 6;
        margin-start: 12;
        margin-end: 12;
        margin-top: 12;
        margin-bottom: 12;

        Box {
          spacing: 12;

          Label {
            label: _("Apply Advanced Power Management Settings");
            hexpand: true;
            xalign: 0;
            ellipsize: end;

            styles [
              "heading",
            ]
          }

          Switch apm-switch {
            has-tooltip: true;
            tooltip-text: _("Turn on to configure APM at startup and when the disk is connected");
          }
        }

        Box apm-widgets-box {
          orientation: vertical;
          spacing: 6;

          Box {
            spacing: 6;

            Label apm-label {
              xalign: 1;
              label: _("APM Level");

              styles [
                "dim-label",
              ]
            }

            Label apm-value-label {}
          }

          Scale apm-scale {
            margin-start: 24;
            margin-end: 24;

            adjustment: Adjustment apm-adjustment {
              lower: 1;
              upper: 255;
              value: 127;
              step-increment: 1;
              page-increment: 10;
            };

            draw-value: false;
          }

          Label {
            xalign: 0;
            label: _(
              "Aggressive spin-down may wear out the drive faster than anticipated. Please check the “Start/Stop Count” SMART attribute from time to time"
            );
            wrap: true;

            styles [
              "caption",
            ]
          }
        }
      }

      [tab]
      Label {
        label: _("A_PM");
        use-underline: true;
        mnemonic-widget: apm-box;
      }

      Box aam-box {
        orientation: vertical;
        spacing: 6;
        margin-start: 12;
        margin-end: 12;
        margin-top: 12;
        margin-bottom: 12;

        Box {
          spacing: 12;

          Label {
            label: _("Apply Automatic Acoustic Management Settings");
            hexpand: true;
            xalign: 0;
            ellipsize: end;

            styles [
              "heading",
            ]
          }

          Switch aam-switch {
            has-tooltip: true;
            tooltip-text: _("Turn on to configure AAM at startup and when the disk is connected");
          }
        }

        Box aam-widgets-box {
          orientation: vertical;
          spacing: 6;

          Grid {
            row-spacing: 6;
            column-spacing: 12;

            Label aam-vendor-recommended-label {
              xalign: 1;
              label: _("Vendor Recommended");

              styles [
                "dim-label",
              ]

              layout {
                column: "0";
                row: "0";
              }
            }

            Label aam-label {
              xalign: 1;
              label: _("AAM Level");

              styles [
                "dim-label",
              ]

              layout {
                column: "0";
                row: "1";
              }
            }

            Label aam-value-label {
              layout {
                column: "1";
                row: "1";
              }
            }

            Label aam-vendor-recommended-value-label {
              layout {
                column: "1";
                row: "0";
              }
            }
          }

          Scale aam-scale {
            margin-start: 24;
            margin-end: 24;

            adjustment: Adjustment aam-adjustment {
              lower: 127;
              upper: 254;
              value: 128;
              step-increment: 1;
              page-increment: 10;
            };

            draw-value: false;
          }
        }
      }

      [tab]
      Label {
        label: _("_AAM");
        use-underline: true;
        mnemonic-widget: aam-box;
      }

      Box write-cache-box {
        orientation: vertical;
        spacing: 6;
        margin-start: 12;
        margin-end: 12;
        margin-top: 12;
        margin-bottom: 12;

        Box {
          spacing: 12;

          Label {
            label: _("Apply Write Cache Settings");
            hexpand: true;
            xalign: 0;
            ellipsize: end;

            styles [
              "heading",
            ]
          }

          Switch write-cache-switch {
            has-tooltip: true;
            tooltip-text: _("Turn on to configure Write Cache setting at startup and when the disk is connected");
          }
        }

        Box write-cache-widgets-box {
          orientation: vertical;
          spacing: 6;

          Box {
            spacing: 12;

            Label {
              xalign: 0;
              label: _("S_etting");
              use-underline: true;
              mnemonic-widget: write-cache-comboboxtext;
              hexpand: true;

              styles [
                "dim-label",
              ]
            }

            ComboBoxText write-cache-comboboxtext {
              entry-text-column: 0;
              id-column: 1;

              items [
                _("Enable Write Cache"),
                _("Disable Write Cache"),
              ]
            }
          }

          Label {
            xalign: 0;
            label: _(
              "Performance is increased by enabling write caching, but leaves the system susceptible to data loss in the event of a power failure"
            );
            wrap: true;

            styles [
              "caption",
            ]
          }
        }
      }

      [tab]
      Label {
        label: _("Wr_ite Cache");
        use-underline: true;
        mnemonic-widget: write-cache-box;
      }
    }
  };
}

using Gtk 4.0;
