Popover info_popover {
  child: Label {
    margin-top: 6;
    margin-bottom: 6;
    margin-start: 6;
    margin-end: 6;
    wrap: true;
    max-width-chars: 50;
    justify: left;
    label: _(
      "Recursive mode changes the ownership of subdirectories and files. This can cause problems if files are owned by other users."
    );
    xalign: 0;
  };
}

using Gtk 4.0;
using Adw 1;

template $GduUnlockDialog: Adw.Dialog {
  title: _("Unlock Volume");

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;
      show-start-title-buttons: false;

      [start]
      Button close_button {
        label: _("_Cancel");
        use-underline: true;
        action-name: "window.close";
      }

      [end]
      Button unlock_button {
        label: _("_Unlock");
        use-underline: true;
        sensitive: false;
        clicked => $on_unlock_clicked_cb() swapped;

        styles [
          "suggested-action",
        ]
      }
    }

    content: Box {
      orientation: vertical;

      Adw.Banner keyring_banner {
        title: _("The encryption passphrase was retrieved from the keyring");
      }

      Adw.Banner veracrypt_banner {
        title: _("This volume might be a VeraCrypt volume as it contains random data.");
      }

      Adw.PreferencesPage {
        Adw.PreferencesGroup {
          title: _("Security Credentials");

          Adw.PasswordEntryRow passphrase_entry {
            title: "Passphrase (If specified)";
            notify::text => $unlock_dialog_update_unlock_button_cb() swapped;
          }

          Adw.EntryRow pim_entry_row {
            title: "PIM (If specified)";
            tooltip-text: "If provided, this specifies the numeric value for the VeraCrypt PIM (Personal Iterations Multiplier) to use for this volume.";
            visible: bind keyfile_chooser.visible;
            notify::text => $unlock_dialog_update_unlock_button_cb() swapped;
          }

          Adw.ActionRow keyfile_row {
            title: _("Keyfiles");
            subtitle: _("None Selected");
            visible: bind keyfile_chooser.visible;

            [suffix]
            Button keyfile_chooser {
              tooltip-text: _("Select Keyfiles");
              icon-name: "folder-open-symbolic";
              valign: center;
              visible: false;
              clicked => $on_keyfile_chooser_clicked_cb(template);

              styles [
                "flat",
              ]
            }
          }
        }

        Adw.PreferencesGroup {
          title: _("Volume Configuration");
          visible: bind keyfile_chooser.visible;

          Adw.ActionRow {
            title: _("Hidden");
            activatable-widget: tcrypt_hidden_switch_row;

            [suffix]
            MenuButton {
              tooltip-text: _("More Information");
              icon-name: "help-about-symbolic";
              valign: center;

              styles [
                "flat",
              ]

              popover: Popover {
                Label {
                  label: _("Instead of unlocking this volume, attempt to unlock a secondary volume hidden inside.");
                  halign: center;
                  margin-bottom: 6;
                  margin-end: 6;
                  margin-start: 6;
                  margin-top: 6;
                  max-width-chars: 50;
                  valign: center;
                  wrap: true;
                }
              };
            }

            [suffix]
            Switch tcrypt_hidden_switch_row {
              valign: center;

              styles [
                "flat",
              ]
            }
          }

          Adw.ActionRow {
            title: _("Windows System");
            activatable-widget: tcrypt_system_switch_row;

            [suffix]
            MenuButton {
              tooltip-text: _("More Information");
              icon-name: "help-about-symbolic";
              valign: center;

              styles [
                "flat",
              ]

              popover: Popover {
                Label {
                  label: _("Unlock an encrypted Windows system partition or drive.");
                  halign: center;
                  margin-bottom: 6;
                  margin-end: 6;
                  margin-start: 6;
                  margin-top: 6;
                  max-width-chars: 50;
                  valign: center;
                  wrap: true;
                }
              };
            }

            [suffix]
            Switch tcrypt_system_switch_row {
              valign: center;

              styles [
                "flat",
              ]
            }
          }
        }
      }
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GduWindow: Adw.ApplicationWindow {
  Adw.Breakpoint {
    condition ("max-width: 682sp")

    setters {
      split_view.collapsed: true;
      drive_view.mobile: "true";
    }
  }

  Adw.OverlaySplitView split_view {
    sidebar-width-fraction: 0.3;

    sidebar: Adw.ToolbarView {
      [top]
      Adw.HeaderBar {
        title-widget: Adw.WindowTitle {
          title: _("Disks");
        };

        [start]
        MenuButton job_progress_button {
          visible: false;
          // TODO: Repalce with DrawingArea and animate
          icon-name: "process-working-symbolic";

          popover: Popover jobs_popover {
            child: ListBox jobs_listbox {
              selection-mode: none;

              styles [
                "boxed-list",
              ]
            };
          };
        }

        [end]
        MenuButton sidebar_menu {
          primary: true;
          icon-name: "open-menu-symbolic";
          menu-model: main_menu;
          tooltip-text: _("Main Menu");
        }
      }

      content: ScrolledWindow {
        hscrollbar-policy: never;

        ListBox drives_listbox {
          vexpand: true;
          selection-mode: single;
          selected-rows-changed => $drive_list_row_selection_changed_cb() swapped;

          styles [
            "navigation-sidebar",
          ]
        }
      };
    };

    content: Adw.ToolbarView {
      [top]
      Adw.HeaderBar {
        show-title: false;

        styles [
          "flat",
        ]

        [start]
        ToggleButton show_sidebar_button {
          visible: bind split_view.collapsed bidirectional;
          active: bind split_view.show-sidebar bidirectional;
          icon-name: "sidebar-show-symbolic";
          tooltip-text: _("Show Sidebar");
        }
      }

      content: Stack main_stack {
        StackPage {
          name: "empty_page";

          child: Adw.StatusPage {
            title: _("No Device Selected");
            icon-name: "drive-multidisk-symbolic";
          };
        }

        StackPage {
          name: "drive_page";

          child: $GduDriveView drive_view {};
        }
      };
    };
  }
}

menu main_menu {
  section {
    item (_("_New Disk Image…"), "app.new_disk_image")
    item (_("_Attach Disk Image…"), "app.attach_disk_image")
